import{_ as t,c as r,o as a,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"TypeScript: proofs inside validated boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/typescript.md","filePath":"frontend/typescript.md"}'),i={name:"frontend/typescript.md"};function o(s,e,d,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="typescript-proofs-inside-validated-boundaries" tabindex="-1">TypeScript: proofs inside validated boundaries <a class="header-anchor" href="#typescript-proofs-inside-validated-boundaries" aria-label="Permalink to “TypeScript: proofs inside validated boundaries”">​</a></h1><p>Prerequisites: JavaScript values, functions, objects, modules and promises. Worked compiler baseline: <strong>TypeScript 5.9.3</strong>, not a claim to cover every later release. Runtime validation and server authorization remain separate obligations.</p><h2 id="reading-order" tabindex="-1"><span class="hub-section-number">1 </span>Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to “1 Reading order”">​</a></h2><ol><li><a href="./../senior_growth/TypeScript/What_is_TS.html">Erased types and execution</a>.</li><li><a href="./../senior_growth/TypeScript/What_are_the_different_types_of_TypeScript_(Built-in_%26_User-defined).html">Structural types, unknown and readonly</a>.</li><li><a href="./../senior_growth/TypeScript/What_&quot;Strict_NULL_check_mode&quot;_means.html">Strict null and property presence</a>.</li><li><a href="./../senior_growth/TypeScript/Explain_the_purpose_of_the_&quot;never&quot;_type_in_TypeScript_How_it&#39;s_different_from_&quot;void&quot;.html">Discriminated unions and never</a>.</li><li><a href="./../senior_growth/TypeScript/Generics.html">Generics and related key/value contracts</a>; conditional/distributive typing is optional after the core examples.</li><li><a href="./../senior_growth/TypeScript/How_would_you_introduce_TS_on_a_project.html">Migration and truthful declarations</a>, then <a href="./../senior_growth/TypeScript/Can_we_write_code_in_TS_if_we_would_like_to_support_older_browsers.html">target, APIs and older browsers</a>.</li></ol><h2 id="narrow-from-evidence" tabindex="-1"><span class="hub-section-number">2 </span>Narrow from evidence <a class="header-anchor" href="#narrow-from-evidence" aria-label="Permalink to “2 Narrow from evidence”">​</a></h2><p>Start external data at unknown. Narrow using discriminants and checks that establish the actual shape; a user-written type predicate is a promise the compiler trusts, so an incomplete guard can lie. A cast and the non-null assertion emit no validator. Parsing must also enforce domain limits, duplicate IDs, ownership/scope and allowed fields where relevant.</p><p>Use a state union such as idle/loading/ready/failed instead of optional fields plus unrelated booleans. An exhaustive switch assigns the remaining value to never; adding a variant should fail until every consumer handles it. An empty ready list is valid data, not a transport error.</p><table tabindex="0"><thead><tr><th>Option or type</th><th>Benefit</th><th>Boundary</th></tr></thead><tbody><tr><td>strict</td><td>Includes null, function and implicit-any checks</td><td>Does not include every stricter compiler flag</td></tr><tr><td>noUncheckedIndexedAccess</td><td>Indexed lookup may be undefined</td><td>Runtime index/array still needs validation</td></tr><tr><td>exactOptionalPropertyTypes</td><td>Absence differs from explicit undefined</td><td>JSON drops undefined object properties</td></tr><tr><td>readonly / Readonly</td><td>Restricts writes through this reference</td><td>Shallow and erased; aliases may mutate</td></tr><tr><td>unknown</td><td>Requires narrowing before use</td><td>Does not itself validate input</td></tr></tbody></table><p>A generic preserves a relationship: <code>getField&lt;T, K extends keyof T&gt;(value: T, key: K): T[K]</code>. It does not manufacture arbitrary T from JSON. Prefer a parser argument that returns the type it actually validates. Keep a simple union when a generic/overload adds no useful relation.</p><h2 id="compiler-bundler-and-runtime-are-separate" tabindex="-1"><span class="hub-section-number">3 </span>Compiler, bundler and runtime are separate <a class="header-anchor" href="#compiler-bundler-and-runtime-are-separate" aria-label="Permalink to “3 Compiler, bundler and runtime are separate”">​</a></h2><p>Choose module resolution to match the actual host: bundler mode for a bundler-owned browser app; NodeNext for a Node ESM package with its package.json and emitted import rules. target changes emitted syntax; lib describes assumed APIs; neither installs a Promise/fetch polyfill. Type-only imports erase; a runtime import can still add a client dependency or cross a server-only boundary.</p><p>The retained <a href="./../workbench/frontend/typescript/boundary.html#runtime-contracts">P-330 boundary starter</a> and <a href="./../workbench/frontend/typescript/boundary.html#companion-check">companion check</a> remain at their existing URLs. They are small starter assets, not a complete HTTP application. Substantial new reference collections belong in <a href="./../workbench/frontend/">the workbench</a>.</p><p>Official references checked 2026-10-27: <a href="https://www.typescriptlang.org/docs/handbook/2/narrowing.html" target="_blank" rel="noreferrer">narrowing</a>, <a href="https://www.typescriptlang.org/docs/handbook/2/generics.html" target="_blank" rel="noreferrer">generics</a>, <a href="https://www.typescriptlang.org/tsconfig/strict.html" target="_blank" rel="noreferrer">strict options</a>, <a href="https://www.typescriptlang.org/docs/handbook/modules/guides/choosing-compiler-options.html" target="_blank" rel="noreferrer">module-resolution guidance</a>. Apply <a href="./../practice/frontend/f04-typescript.html">F04</a>, separately recording compile and runtime evidence.</p>',13)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
